/// Central constants for the local SQLite database.
///
/// A-M1 provides the database file/version plus the shared base columns used
/// by every table. Table names and table-specific column names are added by
/// each subsequent model milestone (A-M2 onwards).
library;

/// On-disk filename of the SQLite database.
const String appDatabaseName = 'al_madina_dairy.db';

/// Current schema version. Starts at 1.
const int appDatabaseVersion = 8;

/// Base column: primary key, a UUID v4 string generated by [IdGenerator].
const String columnId = 'id';

/// Base column: creation timestamp stored as an ISO 8601 string.
const String columnCreatedAt = 'createdAt';

/// Base column: last-modified timestamp stored as an ISO 8601 string.
const String columnUpdatedAt = 'updatedAt';

/// Base column: sync state stored as an integer.
/// 0 = synced, 1 = pending_upload, 2 = pending_update, 3 = pending_delete.
const String columnSyncStatus = 'syncStatus';